<?php
function ur_assets(){static $done=false;if($done)return;$done=true;oi_assets();echo '<link rel="stylesheet" href="assets/unified_receiving.css?v=5.9.51"><script src="assets/unified_receiving.js?v=5.9.51" defer></script>';}
function ur_form_open($action,$extra=[],$upload=false){echo '<form method="post" action="unified_receiving_action.php"'.($upload?' enctype="multipart/form-data"':'').'><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="'.e($action).'">';foreach($extra as $k=>$v)echo '<input type="hidden" name="'.e($k).'" value="'.e($v).'">';}
function ur_form(){ur_assets();echo '<h2>Manual Inflow · Actual Returns</h2>';if(access_page_allowed('return_audit'))echo '<p><a class="btn ghost" href="?page=return_audit">Audit Good Item Return History</a></p>';if(!can_action('return_confirm')){$readPlatform=$_GET['platform']??'Shopee';if(!is_string($readPlatform)||!isset(om_shops()[$readPlatform]))$readPlatform='Shopee';echo '<p class="alert info">Read-only access. Return batches and downloads are available; receiving requires transaction access.</p><div class="tabs">';foreach(om_shops() as $pl=>$shop)echo '<a class="tab" href="?page=inflow&amp;entry=manual&amp;platform='.e($pl).'">'.e($pl).'</a>';echo '</div>';ur_history($readPlatform);return;}ur_require();$draft=$_SESSION['ur_form_draft']??[];$edit=(int)($_GET['ur_edit']??$draft['editing_id']??0);$attachment='';$revision=0;$orders=[];$date=$draft['txn_date']??date('Y-m-d');$platform=$_GET['platform']??$draft['platform']??'Shopee';if(!is_string($platform)||!isset(om_shops()[$platform]))$platform='Shopee';stock_platform($platform);if($edit){$b=return_batch($edit);ur_owner($b);$revision=$b['revision'];$attachment=$b['stored_path']?$b['filename']:'';foreach(json_decode($b['rows_json'],true) as $r){$platform=$r['platform'];$date=$r['date'];$orders[$r['order']]['order']=$r['order'];$orders[$r['order']]['receipt_reference']=$r['receipt_reference']??'';$orders[$r['order']]['tracking_no']=$r['tracking_no']??'';$orders[$r['order']]['return_items_only']=$r['return_items_only']??false;$orders[$r['order']]['return_scope_reason']=$r['return_scope_reason']??'';$orders[$r['order']]['items'][]=['product_id'=>$r['product_id'],'qty'=>$r['qty'],'condition'=>$r['condition']];}$orders=array_values($orders);}elseif(!empty($_GET['ur_order_id'])){$o=om_order((int)$_GET['ur_order_id']);$source=ur_lookup($o['platform'],$o['order_no']);$platform=$o['platform'];$orders=[['order'=>$source['order'],'items'=>array_map(fn($i)=>['product_id'=>$i['product_id'],'qty'=>'','condition'=>'Good Item'],ri_recommended($source))]];}elseif(($draft['platform']??$platform)===$platform){$orders=json_decode((string)($draft['orders_json']??'[]'),true)?:[];}
 $orders=array_values(array_filter($orders,fn($g)=>is_array($g)&&is_scalar($g['order']??'')&&is_array($g['items']??[])));foreach($orders as &$g){$g['order']=(string)($g['order']??'');$g['items']=array_values(array_filter($g['items']??[],fn($i)=>is_array($i)&&is_scalar($i['product_id']??0)&&is_scalar($i['qty']??'')&&is_scalar($i['condition']??'')));}unset($g);
 $products=om_query('SELECT id,master_sku,name FROM products WHERE active=1 ORDER BY name,id')->fetchAll();foreach($orders as &$g){try{$g['source']=ur_lookup($platform,$g['order']);}catch(Throwable $e){$g['error']=$e->getMessage();}$g['items']=$g['items']??[];foreach($g['items'] as &$item){$p=om_query('SELECT id,master_sku,name FROM products WHERE id=?',[(int)$item['product_id']])->fetch();$item['product_text']=$p?$p['master_sku'].' · '.$p['name']:'';}unset($item);}unset($g);$nonce=$draft['form_nonce']??bin2hex(random_bytes(24));if(!preg_match('/^[a-f0-9]{48}$/D',$nonce))$nonce=bin2hex(random_bytes(24));
 echo '<div class="modal-actions"><a class="btn secondary" href="?page=wrong_returns">Wrong Item Received / Claims Cases</a></div>';
 echo '<div class="card ur-form-card"><h3>'.($edit?'Edit Unposted Return Batch':'Return Entry Form').'</h3><p>One platform per batch. Enter Order IDs; recorded dispatches load their original items. Quantities left blank are not received.</p>';ur_form_open('ur_stage',['orders_json'=>'[]','form_nonce'=>$nonce,'editing_id'=>$edit,'revision'=>$revision],true);echo '<div class="ur-header"><label>Received Date<input type="date" name="txn_date" value="'.e($date).'" max="'.date('Y-m-d').'" required></label><label>Platform<select id="ur-platform" name="platform"'.($edit?' disabled':'').'>';foreach(om_shops() as $pl=>$shop)echo '<option value="'.e($pl).'"'.($pl===$platform?' selected':'').'>'.e($pl==='Website'?'Website Selling':$pl).'</option>';echo '</select></label>';if($edit)echo '<input type="hidden" name="platform" value="'.e($platform).'">';echo '<label>Attachment · Optional<input type="file" name="attachment" accept=".pdf,.png,.jpg,.jpeg"></label></div>';if($attachment)echo '<p class="muted">Retained batch attachment: '.e($attachment).'</p>';echo '<div class="ur-table-wrap"><table class="table ur-table" data-server-paginated="1"><thead><tr><th>Order ID / Number</th><th>Tracking No.</th><th>Products / SKU</th><th>Received Qty</th><th>Condition</th><th>Actions</th></tr></thead><tbody id="ur-entry-lines"></tbody></table></div><button type="button" class="btn ghost ur-add-order" data-ur-add-order>+ Add Order ID / Number</button><p class="muted">Recorded but not dispatched orders are handled in Order Monitoring. Enter one Tracking No. per order / returned parcel. Receipt verification is completed in Review.</p><div class="ur-footer"><span id="ur-entry-summary">No items entered.</span><button class="btn primary" id="ur-validate">Validate &amp; Review</button></div></form></div><div id="ur-form-error" role="alert"></div>';
 echo '<script type="application/json" id="ur-bootstrap">'.json_encode(['orders'=>$orders,'products'=>$products,'platform'=>$platform,'csrf'=>csrf_token()],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT).'</script>';ur_history($platform);
}
function ur_effects($rows){$tot=[];foreach($rows as $r){$pid=(int)$r['product_id'];$tot[$pid]??=['good'=>0,'non'=>0];$tot[$pid][$r['condition']==='Good Item'?'good':'non']+=(int)$r['qty'];}$out=[];foreach($tot as $pid=>$v){$s=stock_row($pid);$non=$s['physical']-$s['current'];$out[]=[$s['master_sku'].' · '.$s['name'],$v['good']+$v['non'],$s['current'].' → '.($s['current']+$v['good']),$non.' → '.($non+$v['non']),$s['physical'].' → '.($s['physical']+$v['good']+$v['non'])];}return $out;}
function ur_page($id){ur_assets();$b=return_batch($id);if(!ur_is_batch($b))throw new Exception('Use the original receipt view for this batch.');$a=return_analysis($b);$rows=$a['rows'];$groups=[];foreach($rows as $r)$groups[$r['order']][]=$r;$first=$rows[0]??[];echo '<div class="page-head"><div><h2>Manual Inflow · Verification &amp; Review</h2><p>'.e($b['batch_ref'].' · '.$b['status'].' · '.($first['platform']??'').' · Received '.($first['date']??'')).'</p></div><a class="btn ghost" href="?page=inflow&amp;entry=manual&amp;platform='.e($first['platform']??'Shopee').'">New Return Batch</a></div><div class="card"><div class="om-actions"><a class="btn secondary" href="unified_receiving_action.php?download=xlsx&amp;id='.$id.'">Download Excel</a><a class="btn ghost" target="_blank" href="unified_receiving_action.php?download=print&amp;id='.$id.'">Print / PDF</a>';if($b['stored_path'])echo '<a class="btn ghost" href="batch_document.php?type=return&amp;id='.$id.'" target="_blank">Batch Attachment</a>';echo '</div>';$table=[];foreach($rows as $r)$table[]=[$r['order'],$r['tracking_no']??'',($r['sku']??'').' · '.($r['product_name']??$r['item']),$r['qty'],$r['condition'],rc_destination($b,$r),ur_source_label($r),$r['receipt_reference']?:'Verify below',!empty($r['errors'])?implode(' · ',$r['errors']):(isset($r['return_scope_remaining'])?$r['return_scope_remaining'].' pcs still expected for this return; other order items retained':(isset($r['remaining_after'])&&is_numeric($r['remaining_after'])?$r['remaining_after'].' pcs remaining after this receipt':($r['remaining_after']??'Posted')))];om_table(['Order ID','Tracking No.','Products / SKU','Received Qty','Condition','Stock Destination','Source Remark','Return / Parcel Ref','Verification'],$table);foreach($a['warnings'] as $warning)echo '<p class="alert warn">'.e($warning).'</p>';echo '</div>';
 $editable=$b['status']==='Review'&&can_action('return_confirm')&&(access_profile()==='Admin'||(int)$b['created_by']===current_user()['id']);if($editable){ur_reference_verification($b,$groups,$_SESSION['ur_verify_draft'][$id]??[]);
  echo '<div class="card"><h3>Review Stock Effect</h3>';om_table(['Product / SKU','Quantity (pcs)','Sellable','Non-Sellable','Total Physical'],ur_effects($rows));echo '<p>Good items return to this platform. Damage/Leak and For Repackaging increase Non-Sellable only. No stock changes until confirmation.</p>';foreach($a['errors'] as $error)echo '<p class="alert warn">'.e($error).'</p>';if(!$a['errors']&&return_uploader_allowed($b,$a)){ur_form_open('ur_post',['batch_id'=>$id,'digest'=>$a['digest']]);echo '<label class="oi-ack"><input type="checkbox" name="review_ack" value="1" required> I reviewed each order, source match, quantity, condition and stock effect.</label><p>Do you want to post these verified returns?</p><button class="btn primary" data-confirm="Post these verified return quantities? This adds physical stock once.">Confirm &amp; Post Returns</button></form>';}elseif(!$a['errors'])echo '<p class="alert warn">A similar prior receipt requires Admin review under the existing return policy.</p>';echo '<a class="btn ghost" href="?page=inflow&amp;entry=manual&amp;ur_edit='.$id.'">Back / Correct Form</a>';ur_form_open('ur_cancel',['batch_id'=>$id]);echo '<button class="btn ghost">Cancel Unposted Batch</button></form></div>';}
 foreach($groups as $no=>$items)echo rf_link($items[0]['platform'],(string)$no);if($b['status']==='Posted')ur_posted_history($b,$groups);
}
function ur_history($platform){$all=[];foreach(om_query('SELECT b.*,u.name preparer FROM return_batches b LEFT JOIN users u ON u.id=b.created_by ORDER BY b.id DESC') as $b){if(!ur_is_batch($b))continue;$rows=json_decode($b['rows_json'],true);if($rows[0]['platform']!==$platform)continue;$b['rows']=$rows;$all[]=$b;}$offset=max(0,(int)($_GET['ur_history_offset']??0));$table=[];$links=[];foreach(array_slice($all,$offset,10) as $b){$table[]=[$b['created_at'],$b['batch_ref'],count(array_unique(array_column($b['rows'],'order'))),array_sum(array_column($b['rows'],'qty')),$b['status'],$b['preparer']];$links[]='<a class="btn ghost sm" href="?page=manual_receiving&amp;id='.$b['id'].'">View Details</a>';}echo '<div class="card"><h3>'.e($platform).' · Return Batch History</h3>';om_table(['Recorded','Batch','Orders','Received Qty','Status','Prepared By'],$table,$links);echo rs8_pagination(count($all),$offset,10,$_GET,'ur_history_offset').'</div>';}
function ur_export($b){if(!ur_is_batch($b))throw new Exception('Not a unified return batch.');$a=return_analysis($b);$rows=[];foreach($a['rows'] as $r){$p=om_query('SELECT master_sku,name FROM products WHERE id=?',[$r['product_id']])->fetch();$rows[]=[$r['date'],$r['platform'],(string)$r['order'],$r['tracking_no']??'',$p['master_sku'],$p['name'],$r['qty'],$r['condition'],ur_source_label($r),$r['receipt_reference']??'',$b['status'],implode(' · ',$r['errors']??[]),...or_fields_for_ref($r['order'],$r['platform'])];}return ['title'=>'Unified Manual Inflow '.$b['batch_ref'],'headers'=>['Received Date','Platform','Order ID','Tracking No.','Master SKU','Product','Received Qty','Condition','Source Remark','Return / Parcel Reference','Batch Status','Validation','Reference Type','Booking SN','Assigned Order ID','Original Order Tracking Numbers'],'rows'=>$rows];}

function ur_reference_verification($b,$groups,$draft){
 $drafting=array_key_exists('references',$draft);$unknown=count(array_filter($groups,fn($items)=>$items[0]['source_mode']==='unknown'));$allChecked=$unknown>0;foreach($groups as $no=>$items){$r=$items[0];if($r['source_mode']!=='unknown')continue;$key=hash('sha256',(string)$no);$allChecked=$allChecked&&($drafting?!empty($draft['not_counted'][$key]):!empty($r['not_counted_ack']));}
 echo '<section class="card ur-reference-card"><div class="ur-reference-heading"><div><h3>Verify Return References</h3><p>Enter each parcel reference, verify the details, then confirm the return.</p></div><span class="ur-reference-count">'.count($groups).' orders</span></div>';ur_form_open('ur_verify',['batch_id'=>$b['id'],'revision'=>$b['revision']]);
 if($unknown)echo '<div class="ur-reference-batch-check"><label class="ur-check"><input type="checkbox" data-ur-verify-all '.($allChecked?'checked':'').'><span>I verified all '.$unknown.' unrecorded orders: actual returns, not included in Beginning Balance or another receipt.</span></label><small>You can also verify each order below.</small></div>';
 echo '<table class="table ur-reference-table" data-server-paginated="1"><thead><tr><th>Order / source</th><th>Tracking / Return Reference</th><th>Verification</th><th>Additional verification</th></tr></thead><tbody>';
 foreach($groups as $no=>$items){$r=$items[0];$key=hash('sha256',(string)$no);$separate=$drafting?!empty($draft['separate'][$key]):!empty($r['separate_receipt_ack']);$note=$draft['notes'][$key]??$r['verification_note']??'';$notCounted=$drafting?!empty($draft['not_counted'][$key]):!empty($r['not_counted_ack']);
 echo '<tr><td data-label="Order / source"><b>'.e($no).'</b><small>'.e(ur_source_label($r)).' · '.array_sum(array_column($items,'qty')).' pcs</small></td><td data-label="Tracking / Return Reference"><label class="ur-reference-field"><span class="ur-mobile-label">Tracking / Return Reference</span><input aria-label="Tracking / Return Reference for '.e($no).'" name="references['.$key.']" maxlength="100" value="'.e($draft['references'][$key]??($r['receipt_reference']?:($r['tracking_no']??''))).'" placeholder="Enter parcel reference" required></label></td><td data-label="Verification">';
 if($r['source_mode']==='unknown')echo '<label class="ur-check"><input type="checkbox" data-ur-order-ack name="not_counted['.$key.']" value="1" '.($notCounted?'checked':'').' required><span>Verified: not in starting balance / other receipt</span></label>';else echo '<span class="ur-match-label">Original dispatch matched</span>';
 echo '</td><td data-label="Additional verification"><details class="ur-parcel-verification"'.($separate||trim($note)!==''?' open':'').'><summary>Separate parcel verification</summary><div class="ur-parcel-body"><label class="ur-check"><input type="checkbox" name="separate['.$key.']" value="1" '.($separate?'checked':'').'><span>I verified a different physical parcel.</span></label><label class="ur-reference-field"><span>Verified reference / explanation</span><textarea name="notes['.$key.']" rows="2" maxlength="2000" placeholder="Explain only if this is a separate parcel">'.e($note).'</textarea></label></div></details></td></tr>';
 }
 $physical=$drafting?!empty($draft['physical_ack']):!empty((reset($groups)[0]??[])['physical_ack']);echo '</tbody></table><div class="ur-reference-footer"><label class="ur-check"><input type="checkbox" name="physical_ack" value="1" required '.($physical?'checked':'').'><span>I confirm these quantities were physically received.</span></label><button class="btn secondary">Verify Details &amp; Refresh Review</button></div><p class="ur-reference-note">Verification does not add stock. Confirm &amp; Post Returns remains a separate final action.</p></form></section>';
}

function ur_posted_history($b,$groups){
 $first=(reset($groups)[0]??[]);$size=(int)($_GET['per_page']??10);if(!in_array($size,[10,20,30,50],true))$size=10;$total=count($groups);$offset=min(intdiv(max(0,(int)($_GET['ur_orders_offset']??0)),$size)*$size,max(0,(int)(ceil($total/$size)-1)*$size));$canLink=can_action('return_confirm')&&(access_profile()==='Admin'||(int)$b['created_by']===current_user()['id']);$hasUnknown=(bool)array_filter($groups,fn($items)=>$items[0]['source_mode']==='unknown'&&empty($items[0]['linked_later']));$qty=0;foreach($groups as $items)$qty+=array_sum(array_column($items,'qty'));
 echo '<section class="card ur-posted-history"><div class="ur-posted-heading"><h3>Batch History</h3><span>'.number_format($total).' orders · '.number_format($qty).' pcs</span></div><div class="ur-history-meta">';foreach([['Prepared',$b['created_at'],$b['created_by']],['Verified',$first['verified_at']??'',$first['verified_by']??$b['created_by']],['Posted',$b['posted_at']??'',$b['posted_by']??$b['created_by']]] as $entry)echo '<div><span>'.e($entry[0]).'</span><b>'.e($entry[1]?:'Not recorded').'</b><small>'.e(rs8_user_name($entry[2])).'</small></div>';echo '</div>';
 if($hasUnknown)echo '<p class="ur-history-reminder">Original order not recorded? Link the existing receipt when its dispatch becomes available. Linking does not add stock again.</p>';
 echo '<table class="table ur-posted-table" data-server-paginated="1"><thead><tr><th>Order / Platform</th><th>Return / Parcel Reference</th><th>Quantity</th><th>Source</th><th>Details / Actions</th></tr></thead><tbody>';
 foreach(array_slice($groups,$offset,$size,true) as $no=>$items){$r=$items[0];echo '<tr><td data-label="Order / Platform"><b>'.e($no).'</b><small>'.e($r['platform']==='Website'?'Website Selling':$r['platform']).'</small><small>Tracking No.: '.e(($r['tracking_no']??'')?:'Not recorded').'</small></td><td data-label="Return / Parcel Reference">'.e($r['receipt_reference']??'Not recorded').'</td><td data-label="Quantity" class="ur-posted-quantity">'.number_format(array_sum(array_column($items,'qty'))).' pcs</td><td data-label="Source">'.e(ur_source_label($r)).'</td><td data-label="Details / Actions"><div class="ur-posted-actions"><details class="ur-posted-products"><summary>View Items / Movements</summary><div>';foreach($items as $line){$p=om_query('SELECT master_sku,name FROM products WHERE id=?',[$line['product_id']])->fetch()?:[];echo '<article><b>'.e($p['master_sku']??($line['sku']??'Product')).'</b><span>'.e($p['name']??$line['item']).'</span><small>'.(int)$line['qty'].' pcs · '.e($line['condition']).'</small><a class="btn ghost sm" href="?page=product_detail&amp;id='.(int)$line['product_id'].'&amp;from='.e($line['date']).'&amp;to='.e($line['date']).'">Stock Movements</a></article>';}echo '</div></details>';
 $o=om_find($r['platform'],om_shops()[$r['platform']],(string)$no);if($o)echo '<a class="btn secondary sm" href="?page=order_monitor&amp;order_id='.(int)$o['id'].'">Order History</a>';if($r['source_mode']==='unknown'&&empty($r['linked_later'])&&$canLink){ur_form_open('ur_link',['batch_id'=>$b['id'],'order'=>$no]);echo '<button class="btn ghost sm">Check / Link Original Dispatch</button></form>';}echo '</div></td></tr>';
 }
 echo '</tbody></table>';$params=$_GET;$params['per_page']=$size;$params['page']='manual_receiving';$params['id']=$b['id'];$select='<label class="pagination-size-label"><select data-ur-history-size aria-label="Batch history rows per page">';foreach([10,20,30,50] as $n)$select.='<option value="'.$n.'"'.($n===$size?' selected':'').'>'.$n.'</option>';$select.='</select><span>Rows per page</span></label>';$pagination=rs8_pagination($total,$offset,$size,$params,'ur_orders_offset');echo str_replace('</span></div><div class="pagination-buttons">','</span>'.$select.'</div><div class="pagination-buttons">',$pagination).'</section>';
}
